#!/usr/bin/env python3
"""Recover exact generated bytes from all retained Actions artifacts, not expired CDN URLs."""
import argparse, hashlib, json, shutil
from pathlib import Path
from generate import request_hash
HERE=Path(__file__).resolve().parent

def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda:f.read(1024*1024),b''): h.update(block)
    return h.hexdigest()

def collect(project,receipts,cache,dest):
    dest.mkdir(parents=True,exist_ok=True)
    index={}
    for path in sorted(cache.rglob('S??.mp4')):
        index.setdefault(path.stem,[]).append(path)
    report={'clips':{},'missing':[]}
    for shot in project['shots']:
        if shot['kind']!='cogvideo':continue
        sid=shot['id'];row=receipts['shots'].get(sid,{})
        if row.get('status')!='completed' or row.get('request_hash')!=request_hash(project,shot) or not row.get('sha256'):
            raise RuntimeError('No matching completed receipt: '+sid)
        target=dest/(sid+'.mp4')
        candidates=([target] if target.exists() else [])+index.get(sid,[])
        match=next((p for p in candidates if digest(p)==row['sha256']),None)
        if match is None:
            report['missing'].append(sid);continue
        if match!=target:shutil.copy2(match,target)
        report['clips'][sid]={'sha256':digest(target),'bytes':target.stat().st_size,'restored_from':str(match)}
        print('EXACT_SOURCE',sid,row['sha256'],flush=True)
    return report

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--cache-root',type=Path,required=True);ap.add_argument('--dest',type=Path,required=True);ap.add_argument('--report',type=Path,required=True);a=ap.parse_args()
    report=collect(json.loads((HERE/'story.json').read_text()),json.loads((HERE/'results.json').read_text()),a.cache_root,a.dest)
    a.report.parent.mkdir(parents=True,exist_ok=True);a.report.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
    if report['missing']:raise RuntimeError('Missing exact cached sources (not regenerating): '+','.join(report['missing']))
    print('ALL_EXACT_SOURCES',len(report['clips']),flush=True)
if __name__=='__main__':main()
